package local.liuying.studio;
import android.app.Instrumentation;
import android.content.*;
import android.os.Bundle;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import org.json.*;

public final class HistoryStorageInstrument extends Instrumentation {
 private File directory;private Context context;private int checks;
 private void check(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
 private void reset()throws Exception{if(directory!=null)remove(directory);directory=new File(getTargetContext().getCacheDir(),"history-test-"+System.nanoTime());if(!directory.mkdirs())throw new IOException("Fixture directory");context=new ContextWrapper(getTargetContext()){@Override public File getFilesDir(){return directory;}};}
 private static void remove(File f)throws Exception{if(Files.isSymbolicLink(f.toPath())){Files.delete(f.toPath());return;}f.setWritable(true,false);if(f.isDirectory()){File[] children=f.listFiles();if(children!=null)for(File child:children)remove(child);}Files.deleteIfExists(f.toPath());}
 private JSONObject job(String owner)throws Exception{String token=UUID.randomUUID().toString();String path="prints/"+token+".jpg";File f=new File(directory,path);f.getParentFile().mkdirs();Files.write(f.toPath(),new byte[]{1,2,3,4});return new JSONObject().put("owner",owner).put("token",token).put("batchId",token).put("batchIndex",1).put("batchCount",1).put("phase","done").put("file",path).put("requestId","request-0000000001").put("digest",PrintJobs.digest("synthetic"));}
 private void history(JSONObject...jobs)throws Exception{JSONArray a=new JSONArray();for(JSONObject j:jobs)a.put(j);Store.write(context,"history.json",new JSONObject().put("items",a));}
 private boolean exists(JSONObject j){return new File(directory,j.optString("file")).isFile();}
 private void rejected()throws Exception{boolean failed=false;try{HistoryStorage.clear(context,"local",new JSONArray());}catch(Exception expected){failed=true;}check(failed,"Unsafe cleanup rejected");}
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle result=new Bundle();boolean previousBusy=Store.busy;try{
  check(!Store.busy&&!Store.state(getTargetContext()).optBoolean("unresolved"),"Real printing must be idle");
  reset();JSONObject first=job("local"),second=job("local");String coat=first.getString("file").replace(".jpg",".oc");Files.write(new File(directory,coat).toPath(),new byte[]{5,6,7});first.put("ocFile",coat).put("batchCount",2);second.put("batchId",first.getString("batchId")).put("batchCount",2).put("batchIndex",2);JSONObject oldSecond=new JSONObject(second.toString()).put("phase","prepared");first.put("remaining",new JSONArray().put(oldSecond));history(first,second);Store.write(context,"job.json",new JSONObject(second.toString()));Store.write(context,"web-queue.json",new JSONObject().put("items",new JSONArray().put(new JSONObject(first.toString()))));
  check(HistoryStorage.summary(context,"local",new JSONArray()).getInt("files")==3,"Complete batch includes JPEG and OC despite old prepared snapshot");
  check(HistoryStorage.summary(context,"local",new JSONArray().put("/private/"+second.getString("file"))).getInt("files")==0,"Draft protects entire batch");
  JSONObject cleared=HistoryStorage.clear(context,"local",new JSONArray());check(cleared.getInt("files")==3&&cleared.getLong("bytes")==11,"Exact synthetic files removed");check(!exists(first)&&!exists(second),"Both batch photos deleted");check(PrintJobs.submit(context,"local","request-0000000001","synthetic").optBoolean("duplicate"),"Cleanup retains request deduplication without reprinting");
  JSONObject saved=Store.read(context,"history.json").getJSONArray("items").getJSONObject(0);check(saved.optBoolean("filesCleared")&&!saved.optBoolean("cleanupPending")&&saved.getString("digest").equals(PrintJobs.digest("synthetic")),"Cleared markers retain dedup identity");check(!HistoryStorage.publicJob(saved).has("file")&&!HistoryStorage.publicJob(saved).has("remaining"),"Cleared paths hidden");check(Store.read(context,"job.json").optBoolean("filesCleared"),"Current copy marked");
  boolean reprint=false;try{Reprints.pages(context,"local",first.getString("token"));}catch(IOException expected){reprint=true;}check(reprint,"Cleared work cannot reprint");Store.archive(context,first);check(Store.read(context,"history.json").getJSONArray("items").getJSONObject(0).optBoolean("filesCleared"),"Stale archive cannot revive cleared work");check(HistoryStorage.clear(context,"local",new JSONArray()).getInt("files")==0,"Cleanup idempotent");
  reset();first=job("local");second=job("other");second.put("file",first.getString("file"));history(first,second);check(HistoryStorage.summary(context,"local",null).getInt("files")==0&&exists(first),"Other owner shared reference protected");
  reset();first=job("local");second=job("local");second.put("file",first.getString("file"));history(first,second);check(HistoryStorage.clear(context,"local",null).getInt("files")==1,"Completed same-owner reprint closure removed once");
  reset();first=job("local");second=job("local");second.put("file",first.getString("file")).put("phase","queued");history(first);Store.write(context,"web-queue.json",new JSONObject().put("items",new JSONArray().put(second)));check(HistoryStorage.summary(context,"local",null).getInt("files")==0,"Queued reprint protects original");
  for(String phase:new String[]{"prepared","uncertain","blocked","printing"}){reset();first=job("local");history(first);Store.write(context,"job.json",new JSONObject(first.toString()).put("phase",phase));check(HistoryStorage.summary(context,"local",null).getInt("files")==0,"Unresolved current copy protected: "+phase);}
  reset();first=job("local");first.put("batchCount",2);history(first);check(HistoryStorage.summary(context,"local",null).getInt("files")==0,"Incomplete batch protected");
  reset();first=job("local");history(first);Store.busy=true;try{rejected();check(exists(first),"Busy keeps files");}finally{Store.busy=false;}
  for(String name:new String[]{"history.json","job.json","web-queue.json"}){reset();first=job("local");history(first);Files.write(new File(directory,name).toPath(),"{broken".getBytes("UTF-8"));rejected();check(exists(first),"Corrupt metadata prevents all deletion");}
  reset();first=job("local");history(first);File outside=new File(directory,"source.jpg");Files.write(outside.toPath(),new byte[]{7,8,9});File link=new File(directory,first.getString("file"));Files.delete(link.toPath());Files.createSymbolicLink(link.toPath(),outside.toPath());check(HistoryStorage.summary(context,"local",null).getInt("files")==0&&outside.length()==3,"Symbolic link protected");
  reset();first=job("local");File source=new File(directory,"photos/"+UUID.randomUUID()+".jpg");source.getParentFile().mkdirs();Files.write(source.toPath(),new byte[]{1,2,3});first.put("file","photos/"+source.getName());history(first);check(HistoryStorage.summary(context,"local",null).getInt("files")==0&&source.exists(),"Source photos never deleted");
  reset();first=job("local");history(first);Store.write(context,"web-queue.json",new JSONObject().put("items",new JSONArray()));File broken=new File(directory,"web-queue.json.new");broken.mkdirs();Files.write(new File(broken,"block").toPath(),new byte[]{1});HistoryStorage.summary(context,"local",null);check(new File(broken,"block").isFile(),"Summary does not recover or mutate metadata");rejected();check(exists(first),"Metadata save failure deletes no file");remove(broken);check(HistoryStorage.clear(context,"local",null).getInt("files")==1,"Partial durable marking can retry");
  reset();first=job("local");history(first);File prints=new File(directory,"prints");check(prints.setWritable(false,false),"Make isolated deletion fail");try{cleared=HistoryStorage.clear(context,"local",null);check(cleared.getInt("pending")==1&&exists(first),"Unlink failure remains pending");check(Store.read(context,"history.json").getJSONArray("items").getJSONObject(0).optBoolean("cleanupPending"),"Unlink failure persisted");}finally{prints.setWritable(true,false);}check(HistoryStorage.clear(context,"local",null).getInt("files")==1,"Unlink failure retries");
  result.putString("result","PASS: history cleanup "+checks+" checks; isolated synthetic files only");
 }catch(Throwable error){result.putString("error",android.util.Log.getStackTraceString(error));}finally{try{if(directory!=null)remove(directory);}catch(Exception ignored){}Store.busy=previousBusy;}finish(result.containsKey("error")?1:-1,result);}
}
